module TopModule (
    input  logic clk,
    input  logic areset,
    input  logic bump_left,
    input  logic bump_right,
    input  logic ground,
    input  logic dig,
    output logic walk_left,
    output logic walk_right,
    output logic aaah,
    output logic digging
);

    typedef enum logic [2:0] {
        WL = 3'b000,
        WR = 3'b001,
        DL = 3'b010,
        DR = 3'b011,
        FL = 3'b100,
        FR = 3'b101
    } state_t;

    state_t current_state, next_state;

    always_ff @(posedge clk or posedge areset) begin
        if (areset)
            current_state <= WL;
        else
            current_state <= next_state;
    end

    always_comb begin
        next_state = current_state;
        case (current_state)
            WL: begin
                if (!ground)
                    next_state = FL;
                else if (dig)
                    next_state = DL;
                else if (bump_left || bump_right)
                    next_state = WR;
                else
                    next_state = WL;
            end
            WR: begin
                if (!ground)
                    next_state = FR;
                else if (dig)
                    next_state = DR;
                else if (bump_left || bump_right)
                    next_state = WL;
                else
                    next_state = WR;
            end
            DL: begin
                if (!ground)
                    next_state = FL;
                else
                    next_state = DL;
            end
            DR: begin
                if (!ground)
                    next_state = FR;
                else
                    next_state = DR;
            end
            FL: begin
                if (ground)
                    next_state = WL;
                else
                    next_state = FL;
            end
            FR: begin
                if (ground)
                    next_state = WR;
                else
                    next_state = FR;
            end
            default: next_state = WL;
        endcase
    end

    assign walk_left  = (current_state == WL) || (current_state == FL);
    assign walk_right = (current_state == WR) || (current_state == FR);
    assign aaah       = (current_state == FL) || (current_state == FR);
    assign digging    = (current_state == DL) || (current_state == DR);

endmodule

