module tb_TopModule;
    logic clk;
    logic areset;
    logic bump_left;
    logic bump_right;
    logic ground;
    logic dig;
    logic walk_left;
    logic walk_right;
    logic aaah;
    logic digging;

    TopModule dut (
        .clk(clk),
        .areset(areset),
        .bump_left(bump_left),
        .bump_right(bump_right),
        .ground(ground),
        .dig(dig),
        .walk_left(walk_left),
        .walk_right(walk_right),
        .aaah(aaah),
        .digging(digging)
    );

    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

    initial begin
        areset = 1;
        bump_left = 0;
        bump_right = 0;
        ground = 1;
        dig = 0;
        #12;
        areset = 0;

        // Check reset state: walk_left = 1
        @(posedge clk);
        #1;
        if (!(walk_left == 1 && walk_right == 0 && aaah == 0 && digging == 0)) begin
            $display("SELFFAIL: Reset state incorrect. walk_left=%b, walk_right=%b, aaah=%b, digging=%b", walk_left, walk_right, aaah, digging);
            $finish;
        end

        // Test bump_left (should switch to walk_right)
        @(posedge clk);
        bump_left = 1;
        @(posedge clk);
        bump_left = 0;
        #1;
        if (!(walk_left == 0 && walk_right == 1)) begin
            $display("SELFFAIL: bump_left did not switch to walk_right");
            $finish;
        end

        // Test bump_right (should switch to walk_left)
        @(posedge clk);
        bump_right = 1;
        @(posedge clk);
        bump_right = 0;
        #1;
        if (!(walk_left == 1 && walk_right == 0)) begin
            $display("SELFFAIL: bump_right did not switch to walk_left");
            $finish;
        end

        // Test dig
        @(posedge clk);
        dig = 1;
        @(posedge clk);
        dig = 0;
        #1;
        if (!(digging == 1 && walk_left == 0)) begin
            $display("SELFFAIL: dig did not start digging");
            $finish;
        end

        // Test fall from dig (ground = 0)
        @(posedge clk);
        ground = 0;
        @(posedge clk);
        #1;
        if (!(aaah == 1 && walk_left == 1 && digging == 0)) begin
            $display("SELFFAIL: did not fall left when ground dropped while digging");
            $finish;
        end

        // Ground reappears
        @(posedge clk);
        ground = 1;
        @(posedge clk);
        #1;
        if (!(walk_left == 1 && aaah == 0)) begin
            $display("SELFFAIL: did not resume walking left after fall");
            $finish;
        end

        $display("SELFTEST PASS");
        $finish;
    end
endmodule

module tb_TopModule;
    logic clk;
    logic areset;
    logic bump_left;
    logic bump_right;
    logic ground;
    logic dig;
    logic walk_left;
    logic walk_right;
    logic aaah;
    logic digging;

    TopModule dut (
        .clk(clk),
        .areset(areset),
        .bump_left(bump_left),
        .bump_right(bump_right),
        .ground(ground),
        .dig(dig),
        .walk_left(walk_left),
        .walk_right(walk_right),
        .aaah(aaah),
        .digging(digging)
    );

    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

    initial begin
        areset = 1;
        bump_left = 0;
        bump_right = 0;
        ground = 1;
        dig = 0;
        #12;
        areset = 0;

        // 1. Reset check: WL
        @(posedge clk);
        #1;
        assert (walk_left == 1 && walk_right == 0 && aaah == 0 && digging == 0) else $fatal(1, "Reset failed");

        // 2. Both bumps simultaneously while walking left -> should switch to WR
        @(posedge clk);
        bump_left = 1;
        bump_right = 1;
        @(posedge clk);
        bump_left = 0;
        bump_right = 0;
        #1;
        assert (walk_right == 1) else $fatal(1, "Simultaneous bumps failed");

        // 3. Dig while walking right -> DR
        @(posedge clk);
        dig = 1;
        @(posedge clk);
        dig = 0;
        #1;
        assert (digging == 1 && walk_right == 0) else $fatal(1, "Dig failed");

        // 4. Bump while digging -> should have NO effect (stay DR)
        @(posedge clk);
        bump_left = 1;
        @(posedge clk);
        bump_left = 0;
        #1;
        assert (digging == 1) else $fatal(1, "Bump while digging affected state");

        // 5. Ground drops while digging -> FR (Fall Right)
        @(posedge clk);
        ground = 0;
        @(posedge clk);
        #1;
        assert (aaah == 1 && walk_right == 1) else $fatal(1, "Fall from dig failed");

        // 6. Bump while falling -> should have NO effect
        @(posedge clk);
        bump_left = 1;
        @(posedge clk);
        bump_left = 0;
        #1;
        assert (aaah == 1 && walk_right == 1) else $fatal(1, "Bump while falling affected state");

        // 7. Ground reappears -> WR
        @(posedge clk);
        ground = 1;
        @(posedge clk);
        #1;
        assert (walk_right == 1 && aaah == 0) else $fatal(1, "Resume walking after fall failed");

        // 8. Precedence test: ground=0 and dig=1 simultaneously -> fall should take precedence over dig
        // First switch to WL
        @(posedge clk);
        bump_right = 1;
        @(posedge clk);
        bump_right = 0;
        #1;
        assert (walk_left == 1);

        // Now set ground=0 and dig=1 at the same time
        @(posedge clk);
        ground = 0;
        dig = 1;
        @(posedge clk);
        ground = 1;
        dig = 0;
        #1;
        // Since fall has higher precedence than dig, it should have fallen (aaah=1 during fall cycle)
        // Wait, in the cycle ground=0, it falls.
        // Let's check state during ground=0:
        // In previous cycle we set ground=0 and dig=1. At positive edge, it should transition to FL (fall left).
        // Let's verify aaah was 1.
        assert (aaah == 1) else $fatal(1, "Precedence fall > dig failed");

        $display("SELFTEST PASS");
        $finish;
    end
endmodule
